using System.Text;
using LiteSpec.Model;
using LiteSpec.Standards;

namespace LiteSpec.Cli.Generate;

/// <summary>
///     The names and escapes every generator renderer shares: the generated header, the
///     PascalCase form of record names, the module placeholders of a target path, and the
///     string and documentation escapes of the written languages.
/// </summary>
/// <follows>litespec/core/model#generate-record-determined-code-from-the-records</follows>
static class GenerateNaming
{
    /// <summary>The header line every generated file opens with, before the version.</summary>
    public const string HeaderLine = "// This file is generated by litespec generate from the records. Do not edit it by hand.";

    /// <summary>The header line with the LiteSpec version that wrote it.</summary>
    /// <param name="version">The package version of the LiteSpec release, such as 7.0.0.</param>
    /// <returns>The header line followed by the version.</returns>
    public static string HeaderLineFor(string version) => $"{HeaderLine} LiteSpec {version}.";

    /// <summary>The package version of the carried LiteSpec release, or unknown when none is readable.</summary>
    /// <returns>The version the header stamps, such as 7.0.0 or 7.0.0-rc.1.</returns>
    public static string CurrentVersion() =>
        LiteSpecHome.Version is { } release ? ReleaseVersion.PackageOf(release) : "unknown";

    /// <summary>The PascalCase form of a record module name, such as Spending for spending.</summary>
    /// <param name="module">The record module name.</param>
    /// <returns>The module name in PascalCase.</returns>
    public static string ModulePascal(string module) => Naming.Pascal(module);

    /// <summary>The constant name of a kebab-case record key, such as ReceiptMissing for receipt-missing.</summary>
    /// <param name="key">The kebab-case key.</param>
    /// <returns>The key in PascalCase.</returns>
    public static string ConstName(string key) => Naming.Pascal(key);

    /// <summary>
    ///     Resolves the module placeholders of a target pattern: {Module} reads the
    ///     PascalCase module name and {module} the record module name.
    /// </summary>
    /// <param name="pattern">The path or namespace pattern holding the placeholders.</param>
    /// <param name="module">The record module name.</param>
    /// <returns>The pattern with every placeholder replaced.</returns>
    public static string ResolveModule(string pattern, string module) =>
        pattern.Replace("{Module}", ModulePascal(module), StringComparison.Ordinal)
            .Replace("{module}", module, StringComparison.Ordinal);

    /// <summary>Whether the pattern holds a module placeholder.</summary>
    /// <param name="pattern">The path or namespace pattern.</param>
    /// <returns>True when the pattern holds {Module} or {module}.</returns>
    public static bool HasModulePlaceholder(string pattern) =>
        pattern.Contains("{Module}", StringComparison.Ordinal)
        || pattern.Contains("{module}", StringComparison.Ordinal);

    /// <summary>
    ///     Resolves the aggregate placeholders of a target pattern: {Aggregate} reads the
    ///     PascalCase aggregate folder name and {aggregate} the record aggregate folder name.
    /// </summary>
    /// <param name="pattern">The path or namespace pattern holding the placeholders.</param>
    /// <param name="aggregate">The record aggregate folder name.</param>
    /// <returns>The pattern with every placeholder replaced.</returns>
    public static string ResolveAggregate(string pattern, string aggregate) =>
        pattern.Replace("{Aggregate}", ModulePascal(aggregate), StringComparison.Ordinal)
            .Replace("{aggregate}", aggregate, StringComparison.Ordinal);

    /// <summary>Whether the pattern holds an aggregate placeholder.</summary>
    /// <param name="pattern">The path or namespace pattern.</param>
    /// <returns>True when the pattern holds {Aggregate} or {aggregate}.</returns>
    public static bool HasAggregatePlaceholder(string pattern) =>
        pattern.Contains("{Aggregate}", StringComparison.Ordinal)
        || pattern.Contains("{aggregate}", StringComparison.Ordinal);

    /// <summary>
    ///     Resolves the use-case placeholders of a target pattern: {UseCase} reads the
    ///     PascalCase use-case name and {useCase} the record use-case name.
    /// </summary>
    /// <param name="pattern">The path or namespace pattern holding the placeholders.</param>
    /// <param name="useCase">The record use-case name.</param>
    /// <returns>The pattern with every placeholder replaced.</returns>
    public static string ResolveUseCase(string pattern, string useCase) =>
        pattern.Replace("{UseCase}", ModulePascal(useCase), StringComparison.Ordinal)
            .Replace("{useCase}", useCase, StringComparison.Ordinal);

    /// <summary>Whether the pattern holds a use-case placeholder.</summary>
    /// <param name="pattern">The path or namespace pattern.</param>
    /// <returns>True when the pattern holds {UseCase} or {useCase}.</returns>
    public static bool HasUseCasePlaceholder(string pattern) =>
        pattern.Contains("{UseCase}", StringComparison.Ordinal)
        || pattern.Contains("{useCase}", StringComparison.Ordinal);

    /// <summary>
    ///     Resolves the use-case folders of a target pattern: the aggregate folder drops as a
    ///     whole segment when the use case sits at module level, and the use-case folder reads
    ///     the record use-case name.
    /// </summary>
    /// <param name="pattern">The path or namespace pattern holding the placeholders.</param>
    /// <param name="aggregate">The record aggregate folder name, or null when the use case sits at module level.</param>
    /// <param name="useCase">The record use-case name.</param>
    /// <returns>The pattern with every placeholder replaced.</returns>
    public static string ResolveUseCaseFolders(string pattern, string? aggregate, string useCase)
    {
        if (aggregate is null)
        {
            pattern = pattern.Replace("/{Aggregate}/", "/", StringComparison.Ordinal)
                .Replace("/{aggregate}/", "/", StringComparison.Ordinal)
                .Replace(".{Aggregate}.", ".", StringComparison.Ordinal)
                .Replace(".{aggregate}.", ".", StringComparison.Ordinal)
                .Replace("{Aggregate}", "", StringComparison.Ordinal)
                .Replace("{aggregate}", "", StringComparison.Ordinal)
                .Replace("//", "/", StringComparison.Ordinal)
                .Replace("..", ".", StringComparison.Ordinal);
        }
        else
        {
            pattern = ResolveAggregate(pattern, aggregate);
        }

        return ResolveUseCase(pattern, useCase);
    }

    /// <summary>
    ///     Resolves the knowledge placeholders of a target pattern: {Area} and {Variant} read
    ///     the PascalCase area and variant names, {area} and {variant} the record names.
    /// </summary>
    /// <param name="pattern">The path or namespace pattern holding the placeholders.</param>
    /// <param name="area">The knowledge area name.</param>
    /// <param name="variant">The variant name.</param>
    /// <returns>The pattern with every placeholder replaced.</returns>
    public static string ResolveKnowledge(string pattern, string area, string variant) =>
        pattern.Replace("{Area}", ModulePascal(area), StringComparison.Ordinal)
            .Replace("{area}", area, StringComparison.Ordinal)
            .Replace("{Variant}", ModulePascal(variant), StringComparison.Ordinal)
            .Replace("{variant}", variant, StringComparison.Ordinal);

    /// <summary>Whether the pattern holds a knowledge placeholder.</summary>
    /// <param name="pattern">The path or namespace pattern.</param>
    /// <returns>True when the pattern holds {Area}, {area}, {Variant} or {variant}.</returns>
    public static bool HasKnowledgePlaceholder(string pattern) =>
        pattern.Contains("{Area}", StringComparison.Ordinal)
        || pattern.Contains("{area}", StringComparison.Ordinal)
        || pattern.Contains("{Variant}", StringComparison.Ordinal)
        || pattern.Contains("{variant}", StringComparison.Ordinal);

    /// <summary>
    ///     The constant name of an arbitrary closed-set value: the alphanumeric words in
    ///     PascalCase, Value when no word survives, and an underscore prefix when the name
    ///     would open with a digit.
    /// </summary>
    /// <param name="text">The closed-set value text.</param>
    /// <returns>The sanitized constant name.</returns>
    public static string SanitizeConstName(string text)
    {
        var built = new StringBuilder(text.Length);

        foreach (var part in text.Split(WordSeparators, StringSplitOptions.RemoveEmptyEntries))
        {
            var word = new StringBuilder(part.Length);

            foreach (var character in part)
            {
                if (char.IsLetterOrDigit(character))
                {
                    word.Append(character);
                }
            }

            if (word.Length > 0)
            {
                built.Append(char.ToUpperInvariant(word[0]));
                built.Append(word.ToString(1, word.Length - 1));
            }
        }

        var name = built.ToString();

        if (name.Length == 0)
        {
            return "Value";
        }

        return char.IsDigit(name[0]) ? "_" + name : name;
    }

    /// <summary>The word separators a closed-set value splits on before its words join in PascalCase.</summary>
    private static readonly char[] WordSeparators = ['-', '_', ' ', '.', '/', ':'];

    /// <summary>
    ///     A constant name unused in the set: the candidate, or the candidate with a
    ///     numeric suffix, recording the returned name in the set.
    /// </summary>
    /// <param name="candidate">The preferred constant name.</param>
    /// <param name="taken">The constant names already used, appended in place.</param>
    /// <returns>The candidate, or the candidate with the lowest free numeric suffix.</returns>
    public static string UniqueName(string candidate, HashSet<string> taken)
    {
        if (taken.Add(candidate))
        {
            return candidate;
        }

        for (var suffix = 2; ; suffix++)
        {
            var named = candidate + suffix;

            if (taken.Add(named))
            {
                return named;
            }
        }
    }

    /// <summary>Escapes a value for a C# or TypeScript double-quoted string literal.</summary>
    /// <param name="text">The value text.</param>
    /// <returns>The escaped literal body.</returns>
    public static string EscapeLiteral(string text)
    {
        var built = new StringBuilder(text.Length);

        foreach (var character in text)
        {
            switch (character)
            {
                case '\\':
                    built.Append("\\\\");
                    break;
                case '"':
                    built.Append("\\\"");
                    break;
                case '\r':
                    built.Append("\\r");
                    break;
                case '\n':
                    built.Append("\\n");
                    break;
                case '\t':
                    built.Append("\\t");
                    break;
                default:
                    if (char.IsControl(character))
                    {
                        built.Append("\\u");
                        built.Append(((int)character).ToString("x4", System.Globalization.CultureInfo.InvariantCulture));
                    }
                    else
                    {
                        built.Append(character);
                    }

                    break;
            }
        }

        return built.ToString();
    }

    /// <summary>Escapes a text for an XML documentation element body.</summary>
    /// <param name="text">The documentation text.</param>
    /// <returns>The escaped documentation body.</returns>
    public static string EscapeXml(string text) =>
        text.Replace("&", "&amp;", StringComparison.Ordinal)
            .Replace("<", "&lt;", StringComparison.Ordinal)
            .Replace(">", "&gt;", StringComparison.Ordinal);

    /// <summary>
    ///     The documentation lines of a meaning: one summary line, or one line per
    ///     meaning line, each escaped and prefixed.
    /// </summary>
    /// <param name="meaning">The meaning text.</param>
    /// <param name="indent">The indentation before each documentation line.</param>
    /// <returns>The documentation lines.</returns>
    public static List<string> XmlDocLines(string meaning, string indent)
    {
        var lines = meaning.Replace("\r\n", "\n", StringComparison.Ordinal).Split('\n');

        if (lines.Length == 1)
        {
            return [$"{indent}/// <summary>{EscapeXml(lines[0])}</summary>"];
        }

        var doc = new List<string> { $"{indent}/// <summary>{EscapeXml(lines[0])}" };

        for (var index = 1; index < lines.Length; index++)
        {
            doc.Add($"{indent}/// {EscapeXml(lines[index])}");
        }

        doc.Add($"{indent}/// </summary>");

        return doc;
    }
}
